#!/bin/bash
# Read-only collection for the io-irq-background dimension. Writes only under $D.
D=/home/jhan/workspace/intel-AMX/exec/3b35-inspect-20261112
H=$(hostname -s)
o() { local n=$1; shift; { echo "# host=$H date=$(date -u +%FT%TZ)"; echo "# cmd: $*"; timeout 60 bash -c "$*" 2>&1; } > "$D/io-irq-background-$H-$n.txt"; }
o services 'systemctl list-units --type=service --state=running --no-pager --no-legend | awk "{print \$1}" | sort'
o uptime 'uptime; uptime -s; who -b; cat /proc/loadavg; uname -r; cat /proc/cmdline'
o pstop 'ps -eo pid,user,psr,pcpu,pmem,nlwp,cls,rtprio,etimes,comm,args --sort=-pcpu | cut -c1-220 | head -45'
o kthreads 'ps -eo pid,psr,pcpu,cls,rtprio,comm --ppid 2 --sort=-pcpu | head -25; echo; echo "kthread count:"; ps --ppid 2 -o pid= | wc -l; echo "RT (FF/RR) tasks:"; ps -eLo cls,rtprio,comm | awk "\$1==\"FF\"||\$1==\"RR\"{print \$1,\$2,\$3}" | sed "s#/[0-9]*\$##" | sort | uniq -c | sort -rn | head -20'
o irq 'systemctl is-active irqbalance; systemctl is-enabled irqbalance; pgrep -a irqbalance; echo; cat /proc/irq/default_smp_affinity; echo; lscpu | grep -E "^NUMA node|^CPU\(s\)|Thread|Socket|On-line|Off-line"'
o interrupts 'cat /proc/interrupts'
o isol 'for f in isolated nohz_full offline online possible present; do echo "$f: $(cat /sys/devices/system/cpu/$f 2>&1)"; done; echo "smt/control: $(cat /sys/devices/system/cpu/smt/control)"; echo "smt/active: $(cat /sys/devices/system/cpu/smt/active)"; echo "rcu_nocbs etc in cmdline:"; cat /proc/cmdline'
o cgroup 'echo "root effective: $(cat /sys/fs/cgroup/cpuset.cpus.effective 2>&1)"; for s in user.slice system.slice machine.slice; do echo "$s cpuset.cpus=$(cat /sys/fs/cgroup/$s/cpuset.cpus 2>&1) effective=$(cat /sys/fs/cgroup/$s/cpuset.cpus.effective 2>&1)"; done; echo "controllers: $(cat /sys/fs/cgroup/cgroup.controllers)"; echo "subtree: $(cat /sys/fs/cgroup/cgroup.subtree_control)"; echo; echo "AllowedCPUs per slice:"; for u in $(systemctl list-units --type=slice --no-legend --no-pager | awk "{print \$1}"); do echo "$u $(systemctl show $u -p AllowedCPUs -p CPUQuotaPerSecUSec -p CPUWeight | tr "\n" " ")"; done; echo; echo "services with AllowedCPUs/CPUAffinity/NUMAPolicy set:"; for u in $(systemctl list-units --type=service --state=running --no-legend --no-pager | awk "{print \$1}"); do r=$(systemctl show $u -p AllowedCPUs -p CPUAffinity -p NUMAPolicy -p CPUQuotaPerSecUSec | grep -vE "=$|=infinity$|=n/a$" | tr "\n" " "); [ -n "$r" ] && echo "$u $r"; done; echo; echo "my own cpuset: $(cat /proc/self/cgroup)"; grep -E "Cpus_allowed_list|Mems_allowed_list" /proc/self/status'
o containers 'ps -eo pid,psr,pcpu,pmem,etimes,comm,args | grep -E "dockerd|containerd|podman|crio|kubelet|runc|conmon|qemu|libvirt" | grep -v grep | cut -c1-200; echo; echo "container shims count: $(pgrep -fc containerd-shim)"'
o mounts 'mount | grep -E " type (nfs|nfs4|cifs|fuse|ceph|lustre|beegfs)" ; echo; cat /proc/mounts | grep -E "hugetlbfs|tmpfs /dev/shm|/var/tmp|/scratch|/tmp "'
o disks 'lsblk -o NAME,SIZE,TYPE,ROTA,MODEL,FSTYPE,MOUNTPOINT,SCHED 2>&1; echo; df -hT / /var/tmp /scratch /tmp /home /dev/shm /nix 2>&1; echo; cat /proc/swaps; echo; for q in /sys/block/*/queue/scheduler; do echo "$q $(cat $q)"; done | grep -v loop'
o nic 'for n in /sys/class/net/*; do i=$(basename $n); echo "$i state=$(cat $n/operstate) speed=$(cat $n/speed 2>/dev/null) mtu=$(cat $n/mtu) driver=$(basename $(readlink $n/device/driver 2>/dev/null) 2>/dev/null) numa=$(cat $n/device/numa_node 2>/dev/null) queues_rx=$(ls -d $n/queues/rx-* 2>/dev/null | wc -l)"; done; echo; ip -br addr'
o lspci 'lspci -nn | sed -E "s/^[0-9a-f:.]+ ([^:]+ \[[0-9a-f]{4}\]):.*/\1/" | sort | uniq -c; echo; echo "--- non-Intel-chipset devices:"; lspci -nn | grep -Ei "xilinx|amd|altera|nvidia|mellanox|broadcom|nvme|non-volatile|ethernet|processing accel|co-processor|vga|raid|sas|1e3a|positron" '
o lspcifull 'lspci -nn'
o taint 'echo "tainted: $(cat /proc/sys/kernel/tainted)"; echo "dmesg_restrict: $(cat /proc/sys/kernel/dmesg_restrict)"; echo "--- dmesg tail:"; dmesg 2>&1 | tail -40; echo "--- journalctl -k -n 50:"; journalctl -k -n 50 --no-pager 2>&1 | tail -55; echo "--- modules (out of tree / proprietary flags):"; for m in /sys/module/*/taint; do t=$(cat $m 2>/dev/null); [ -n "$t" ] && echo "$(basename $(dirname $m)) $t"; done'
o edac 'ls /sys/devices/system/edac/mc/ 2>&1; for f in /sys/devices/system/edac/mc/mc*/ce_count /sys/devices/system/edac/mc/mc*/ue_count /sys/devices/system/edac/mc/mc*/ce_noinfo_count /sys/devices/system/edac/mc/mc*/ue_noinfo_count; do [ -e $f ] && echo "$f $(cat $f)"; done; echo "edac modules: $(lsmod | grep -i edac | awk "{print \$1}" | tr "\n" " ")"; echo "MCE/MCP lines in /proc/interrupts:"; grep -E "^ *(MCE|MCP|TRM|THR|DFR|NMI|PMI|LOC|RES|CAL|TLB):" /proc/interrupts | awk "{s=0; for(i=2;i<=NF;i++) if(\$i ~ /^[0-9]+\$/) s+=\$i; print \$1, s}"; echo "mcelog/rasdaemon: $(pgrep -a "mcelog|rasdaemon")"'
o thermal 'c=0;p=0;ct=0;pt=0; for d in /sys/devices/system/cpu/cpu[0-9]*/thermal_throttle; do c=$((c+$(cat $d/core_throttle_count))); p=$((p+$(cat $d/package_throttle_count))); [ -e $d/core_throttle_total_time_ms ] && ct=$((ct+$(cat $d/core_throttle_total_time_ms))); [ -e $d/package_throttle_total_time_ms ] && pt=$((pt+$(cat $d/package_throttle_total_time_ms))); done; echo "sum core_throttle_count=$c"; echo "sum package_throttle_count(over all cpus)=$p"; echo "sum core_throttle_total_time_ms=$ct"; echo "sum package_throttle_total_time_ms=$pt"; echo "cpus with dir: $(ls -d /sys/devices/system/cpu/cpu[0-9]*/thermal_throttle | wc -l)"; echo "cpu0 pkg count=$(cat /sys/devices/system/cpu/cpu0/thermal_throttle/package_throttle_count)"; echo "nonzero core counts: $(grep -L "^0$" /sys/devices/system/cpu/cpu[0-9]*/thermal_throttle/core_throttle_count 2>/dev/null | wc -l)"; echo "max pkg count per cpu: $(cat /sys/devices/system/cpu/cpu[0-9]*/thermal_throttle/package_throttle_count | sort -n | tail -1)"; for z in /sys/class/thermal/thermal_zone*; do echo "$(cat $z/type) $(cat $z/temp 2>/dev/null)"; done | head -8'
o watchdog 'for k in kernel.watchdog kernel.nmi_watchdog kernel.soft_watchdog kernel.watchdog_thresh kernel.watchdog_cpumask kernel.hardlockup_panic kernel.softlockup_panic kernel.numa_balancing kernel.timer_migration kernel.perf_event_paranoid kernel.perf_cpu_time_max_percent kernel.perf_event_max_sample_rate kernel.randomize_va_space kernel.kptr_restrict vm.stat_interval vm.swappiness vm.zone_reclaim_mode vm.compaction_proactiveness vm.dirty_ratio vm.dirty_background_ratio vm.nr_hugepages vm.overcommit_memory; do echo "$k = $(sysctl -n $k 2>&1)"; done; echo "ksm run: $(cat /sys/kernel/mm/ksm/run)"; echo "thp: $(cat /sys/kernel/mm/transparent_hugepage/enabled) defrag: $(cat /sys/kernel/mm/transparent_hugepage/defrag)"'
o sched 'sysctl -a 2>/dev/null | grep -E "^kernel\.sched" | sort; echo "--- debugfs sched (may need root):"; for f in /sys/kernel/debug/sched/*; do [ -f $f ] && echo "$f $(cat $f 2>&1 | head -1)"; done 2>&1 | head -20; echo "preempt: $(cat /sys/kernel/debug/sched/preempt 2>&1)"; grep -E "PREEMPT|CONFIG_HZ=|CONFIG_NO_HZ" /boot/config-$(uname -r) 2>&1; uname -v'
o clock 'echo "current: $(cat /sys/devices/system/clocksource/clocksource0/current_clocksource)"; echo "available: $(cat /sys/devices/system/clocksource/clocksource0/available_clocksource)"; for f in constant_tsc nonstop_tsc tsc_known_freq tsc_adjust tsc_deadline_timer rdtscp invariant_tsc art; do echo "$f: $(grep -m1 "^flags" /proc/cpuinfo | tr " " "\n" | grep -cx $f)"; done; echo "--- tsc lines in kernel log:"; (dmesg 2>/dev/null || journalctl -k -b --no-pager 2>/dev/null) | grep -iE "tsc|clocksource" | head -20; echo "chrony/ntp: $(pgrep -a "chronyd|ntpd|systemd-timesyn")"; timedatectl 2>&1 | grep -E "synchronized|NTP"'
echo done $H
